-- Catálogo único Degrau → Entrega → Checklist. Histórico permanece nos IDs originais.
begin;
create table public.cb_deliveries (
 id text primary key,
 stage_id text not null references public.cb_method_stages(id),
 name text not null check(length(trim(name))>0),
 position integer not null,
 unique(id,stage_id), unique(stage_id,position)
);
create table public.cb_delivery_artifacts (
 delivery_id text not null,
 stage_id text not null,
 artifact_id uuid not null references public.artifacts(id) on delete cascade,
 primary key(delivery_id,artifact_id),
 foreign key(delivery_id,stage_id) references public.cb_deliveries(id,stage_id),
 unique(stage_id,artifact_id)
);
create index cb_delivery_artifacts_artifact_idx on public.cb_delivery_artifacts(artifact_id);
-- Só vínculos explícitos. Renomear um processo não muda sua entrega.
