insert into public.cb_delivery_artifacts(delivery_id,stage_id,artifact_id)
 select d.delivery_id,d.stage_id,a.id
 from jsonb_to_recordset('[{"delivery_id":"D01/diagnostico","stage_id":"D01","artifact_name":"Onboarding"},{"delivery_id":"D02/conteudo","stage_id":"D02","artifact_name":"Linha Editorial"},{"delivery_id":"D03/sistema","stage_id":"D03","artifact_name":"Sistema Black"},{"delivery_id":"D03/rastreio","stage_id":"D03","artifact_name":"Tracker Black"},{"delivery_id":"D04/formacao","stage_id":"D04","artifact_name":"Treinamento comercial"},{"delivery_id":"D05/site","stage_id":"D05","artifact_name":"Site Institucional"},{"delivery_id":"D05/google","stage_id":"D05","artifact_name":"GBP"},{"delivery_id":"D05/comentarios","stage_id":"D05","artifact_name":"Agente de comentários"},{"delivery_id":"D06/vsl","stage_id":"D06","artifact_name":"Funil VSL"},{"delivery_id":"D06/meta","stage_id":"D06","artifact_name":"Meta Ads"},{"delivery_id":"D06/google","stage_id":"D06","artifact_name":"Google Ads"},{"delivery_id":"D06/rastreio","stage_id":"D06","artifact_name":"Tracker Black"},{"delivery_id":"D09/preparo","stage_id":"D09","artifact_name":"Treinamento comercial"},{"delivery_id":"D10/consulta","stage_id":"D10","artifact_name":"Treinamento comercial"},{"delivery_id":"TREINO/vendas","stage_id":"TREINO","artifact_name":"Treinamento comercial"}]'::jsonb) as d(delivery_id text,stage_id text,artifact_name text)
 join public.artifacts a on a.nome=d.artifact_name and d.stage_id=any(a.method_steps)
 where a.archived_at is null and a.tipo='artefato';
