alter table public.cb_checklist_catalog alter column delivery_id set not null;
alter table public.cb_checklist_catalog add constraint cb_checklist_delivery_fk
 foreign key(delivery_id,method_step) references public.cb_deliveries(id,stage_id);
create index cb_checklist_delivery_idx on public.cb_checklist_catalog(delivery_id,method_step);
alter table public.cb_deliveries enable row level security;
alter table public.cb_delivery_artifacts enable row level security;
revoke all on public.cb_deliveries,public.cb_delivery_artifacts from public,anon,authenticated;
grant select on public.cb_deliveries,public.cb_delivery_artifacts to authenticated;
create policy delivery_read on public.cb_deliveries for select to authenticated using (
 (select public.is_admin()) or exists(select 1 from public.members where user_id=(select auth.uid()) and ativo)
);
create policy delivery_artifact_read on public.cb_delivery_artifacts for select to authenticated using (
 exists(select 1 from public.artifacts a where a.id=artifact_id and a.archived_at is null
 and a.tipo='artefato' and cb_delivery_artifacts.stage_id=any(a.method_steps)
 and (not coalesce(a.somente_equipe,false) or (select public.is_admin())))
);
comment on table public.cb_deliveries is 'Entregas por resultado, catálogo comum de Progressão, Processos e Subida.';
comment on table public.cb_delivery_artifacts is 'Vínculos explícitos aos processos existentes; não copia etapas nem progresso. Requer vínculo do processo ao mesmo degrau.';
comment on column public.cb_checklist_catalog.delivery_id is 'Cada item pertence a uma entrega do próprio degrau.';
commit;
